export default async function readLabelMessages({ sourceLabelId, maxResults }, context) {
  const result = await context.actions.gmail.fetch_emails({ labelIds: [sourceLabelId], maxResults, detail: 'full' });
  return { messages: result.messages, sourceLabelId };
}

