export default async function removeMessageLabel({ messages, sourceLabelId }, context) {
  const modified = [];
  for (const message of messages) {
    if (typeof message.messageId !== 'string' || !message.messageId) throw new Error('Gmail returned a message without its ID');
    modified.push(await context.actions.gmail.add_label_to_email({ messageId: message.messageId, removeLabelIds: [sourceLabelId] }));
  }
  return { messages: modified, count: modified.length };
}

