export default async function addMessageLabel({ messages, destinationLabelId }, context) {
  const modified = [];
  for (const message of messages) {
    modified.push(await context.actions.gmail.add_label_to_email({ messageId: message.messageId, addLabelIds: [destinationLabelId] }));
  }
  return { messages: modified, count: modified.length };
}
